<?php
/**
 * Plugin Name: CMP e2e fixture (B7.1)
 * Description: Test-only mu-plugin, mounted by bin/e2e.sh into a throwaway
 *              WordPress Playground. Never ship or install it on a real site.
 *
 * Prints, for every service in data/services.json, a real tracker fragment as
 * a theme would (scripts in wp_head, inline snippets in wp_footer, iframes in
 * a page's content via [cmp_e2e_embeds]). The fragments are generated by
 * tests/e2e/fixture.js into cmp-e2e-fragments.json next to this file.
 */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

define( 'CMP_E2E', true );

/** Loopback request only (the fixture never answers a public host). */
function cmp_e2e_local_request() {
	$host = isset( $_SERVER['HTTP_HOST'] ) ? strtolower( (string) $_SERVER['HTTP_HOST'] ) : '';
	$host = preg_replace( '/:\d+$/', '', $host );
	return in_array( $host, array( '127.0.0.1', 'localhost', '[::1]' ), true );
}

/** The generated fragments (empty arrays when the file is missing). */
function cmp_e2e_data() {
	static $data = null;
	if ( null === $data ) {
		$file = __DIR__ . '/cmp-e2e-fragments.json';
		$data = is_readable( $file ) ? json_decode( (string) file_get_contents( $file ), true ) : array();
		$data = is_array( $data ) ? $data : array();
	}
	return $data;
}

function cmp_e2e_part( $key ) {
	$d = cmp_e2e_data();
	return isset( $d['wp'][ $key ] ) && is_string( $d['wp'][ $key ] ) ? $d['wp'][ $key ] : '';
}

// No server-side traffic to third parties either (thumbnails, update checks, …).
add_filter(
	'pre_http_request',
	function ( $pre, $args, $url ) {
		$host = strtolower( (string) wp_parse_url( (string) $url, PHP_URL_HOST ) );
		if ( in_array( $host, array( '127.0.0.1', 'localhost' ), true ) ) {
			return $pre;
		}
		return new WP_Error( 'cmp_e2e_offline', 'CMP e2e: external HTTP disabled' );
	},
	1,
	3
);

/**
 * Measurement mode per browser context, without stored state: the runner sets
 * the cookie cmp_e2e_mode = strict | advanced | unblocked. "unblocked" turns
 * script blocking off: the negative control that proves the detector sees the
 * fixture's trackers. No cookie = the stored (default) settings.
 */
add_filter(
	'option_cmp_settings',
	function ( $v ) {
		if ( ! cmp_e2e_local_request() || ! isset( $_COOKIE['cmp_e2e_mode'] ) ) {
			return $v;
		}
		$v    = is_array( $v ) ? $v : array();
		$mode = (string) $_COOKIE['cmp_e2e_mode'];
		if ( 'advanced' === $mode ) {
			$v['mode']          = 'pro';
			$v['block_scripts'] = true;
			$v['measurement']   = 'advanced';
		} elseif ( 'unblocked' === $mode ) {
			$v['mode']          = 'pro';
			$v['block_scripts'] = false;
			$v['measurement']   = 'strict';
		} elseif ( 'strict' === $mode ) {
			$v['mode']          = 'pro';
			$v['block_scripts'] = true;
			$v['measurement']   = 'strict';
		}
		return $v;
	}
);

add_action(
	'wp_head',
	function () {
		echo "\n<!-- cmp-e2e-fixture: head -->\n" . cmp_e2e_part( 'head' ) . "\n"; // phpcs:ignore WordPress.Security.EscapeOutput
	},
	1
);

add_action(
	'wp_footer',
	function () {
		echo "\n<!-- cmp-e2e-fixture: footer -->\n" . cmp_e2e_part( 'footer' ) . "\n"; // phpcs:ignore WordPress.Security.EscapeOutput
	},
	100
);

add_shortcode(
	'cmp_e2e_embeds',
	function () {
		return "\n<!-- cmp-e2e-fixture: content -->\n<div data-cmp-e2e-fixture>" . cmp_e2e_part( 'content' ) . "</div>\n";
	}
);
